import {BadRequestException, NotFoundException} from '@nestjs/common';
import {Doc, HeadJson} from 'shared';
import {DocumentsService} from './documents.service';

// code entirely generated by claude. Minor changes and comments added by me.
describe('DocumentsService', () => {
    let service: DocumentsService;

    // mock file but only necessary fields.
    const file = (text: string, name = 'test.txt') =>
        ({originalname: name, buffer: Buffer.from(text, 'latin1')}) as Express.Multer.File;


    beforeEach(() => {
        // create new documents service for each test-case
        service = new DocumentsService();
    });

    describe('uploadFile', () => {
        it('throws error when no file content is set', () => {
            expect(() => service.uploadFile(file(''))).toThrow(BadRequestException);
        });

        it('throws error when file has no content except new lines', () => {
            expect(() => service.uploadFile(file('\r\n  \r\n'))).toThrow(BadRequestException);
        });

        it('expects lines before HEAD as error', () => {
            const result = service.uploadFile(file('POS|1\r\nPOS|2'));

            expect(result).toHaveLength(1);
            expect(result[0]).toMatchObject({
                isSuccess: false,
                errorMsg: expect.stringContaining('vor dem ersten HEAD'),
            });
        });

        it('isn\'t successful if type is not recognized', () => {
            const result = service.uploadFile(file('HEAD|a\r\nXYZ|1'));

            expect(result[0]).toMatchObject({
                isSuccess: false,
                errorMsg: expect.stringContaining('Zeile 2'),
            });
        });

        it('expect one doc per head', () => {
            const result = service.uploadFile(file('HEAD|a\r\nHEAD|b\r\nHEAD|c'));

            expect(result).toHaveLength(3);
            expect(result.every((d) => !d.isSuccess)).toBe(true);
        });

        it('ignores empty lines at end of file', () => {
            const result = service.uploadFile(file('HEAD|a\r\n\r\n\r\n'));

            expect(result).toHaveLength(1);
        });

        it('adds file name and sets unique id', () => {
            const result = service.uploadFile(file('HEAD|a\r\nHEAD|b', 'rechnungen.txt'));

            expect(result.every((d) => d.originalFileName === 'rechnungen.txt')).toBe(true);
            // set takes only unique values. If both ids would be the same this check would fail.
            expect(new Set(result.map((d) => d.id)).size).toBe(2);
        });
    });

    describe('getAllDocuments', () => {
        it('is empty at the beginning', () => {
            expect(service.getAllDocuments()).toEqual([]);
        });

        it('upload a file and cache now stores new files', () => {
            const result = service.uploadFile(file('HEAD|a\r\nHEAD|b'));

            expect(service.getAllDocuments()).toEqual(result);
        });

        it('caches documents for different uploads', () => {
            service.uploadFile(file('HEAD|a'));
            expect(service.getAllDocuments()).toHaveLength(1);

            service.uploadFile(file('HEAD|b'));

            expect(service.getAllDocuments()).toHaveLength(2);
        });
    });

    describe('getJsonForId', () => {
        it('throws not found if id is unknown', () => {
            expect(() => service.getJsonForId('gibt-es-nicht')).toThrow(NotFoundException);
        });

        // adds a document directly to cache with all required data for download
        const addDocToCache = (originalFileName: string, ohtdon: string, isSuccess = true): string => {
            const doc: Doc = {
                id: 'id-1',
                originalFileName,
                isSuccess,
                data: {OHTDON: ohtdon} as HeadJson,
            };
            service['docs'].push(doc);
            return doc.id;
        };

        it('throws bad request if isSuccess is false', () => {
            const id = addDocToCache('rechnungen.txt', 'RE-1', false);

            expect(() => service.getJsonForId(id)).toThrow(BadRequestException);
        });

        it('constructs filename from original file name and OHTDON', () => {
            const id = addDocToCache('rechnungen.txt', 'RE-1');

            expect(service.getJsonForId(id).fileName).toBe('rechnungen_RE-1.json');
        });

        it('removes new lines to prevent header injection', () => {
            const id = addDocToCache('a".txt', 'x"\r\nSet-Cookie: evil');

            const {fileName} = service.getJsonForId(id);

            expect(fileName).not.toMatch(/["\r\n]/);
        });
    });
});